(886846, 101423, 17245, '<td valign="top">Cool.</td>', 'Cool.', '2004-09-01 03:03:39.000000', NULL, 1),
(886850, 100830, 20613, '<td valign="top">Yes!  Finally, a good, appealing shot.  THank you.  10.</td>', 'Yes!  Finally, a good, appealing shot.  THank you.  10.', '2004-09-01 03:04:43.000000', NULL, 1),
(886851, 101199, 20613, '<td valign="top">Simple, but effective :)  I like it.</td>', 'Simple, but effective :)  I like it.', '2004-09-01 03:04:58.000000', NULL, 1),
