(887782, 101903, 25483, '<td valign="top">A lovely photo :)</td>', 'A lovely photo :)', '2004-09-01 11:59:56.000000', NULL, 1),
(887785, 100233, 25483, '<td valign="top">Great idea... 7</td>', 'Great idea... 7', '2004-09-01 12:00:34.000000', NULL, 1),
