INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(888609, 100082, 18799, '<td valign="top">Good Job!  I think I would have cropped closer on the top but that just my opinion, either way, its a good representation of the challenge as I interpret it   8</td>', 'Good Job!  I think I would have cropped closer on the top but that just my opinion, either way, its a good representation of the challenge as I interpret it   8', '2004-09-01 19:05:34.000000', NULL, 1),
(888610, 101857, 25623, '<td valign="top">Why did you leave the coveralls blue?  The picture would have been a LOT better in just b&amp;w.  The blue draws your focus away from the rest of the photograph.</td>', 'Why did you leave the coveralls blue?  The picture would have been a LOT better in just b&w.  The blue draws your focus away from the rest of the photograph.', '2004-09-01 19:05:37.000000', NULL, 1),
(888611, 101794, 7599, '<td valign="top">I think I just fell in love. In my opinion the curl on the nose is the selling point. Very cute and the way the girl is not just in the frame, but interactive with it is fantastic.</td>', 'I think I just fell in love. In my opinion the curl on the nose is the selling point. Very cute and the way the girl is not just in the frame, but interactive with it is fantastic.', '2004-09-01 19:07:33.000000', NULL, 1),
(888612, 100710, 18799, '<td valign="top">I''m sorry, what was the frame part?   Way over exposed too.</td>', 'I''m sorry, what was the frame part?   Way over exposed too.', '2004-09-01 19:08:17.000000', NULL, 1),
(888614, 101860, 22010, '<td valign="top">The first on topic, sharp picture that didn''t take me long to see the "frame". Nice.</td>', 'The first on topic, sharp picture that didn''t take me long to see the "frame". Nice.', '2004-09-01 19:08:39.000000', NULL, 1),
(888615, 101807, 18799, '<td valign="top">The frame is....?</td>', 'The frame is....?', '2004-09-01 19:08:43.000000', NULL, 1),
