(888622, 100662, 7599, '<td valign="top">Wonderful!!! Two things I wish could be adjusted, one the "frame" is cropped at the top, and two the light is a bit distracting. Overall the picture is awesome and more then compensates for my picky points.</td>', 'Wonderful!!! Two things I wish could be adjusted, one the "frame" is cropped at the top, and two the light is a bit distracting. Overall the picture is awesome and more then compensates for my picky points.', '2004-09-01 19:11:54.000000', NULL, 1),
(888623, 100852, 7599, '<td valign="top">Very nice, using art to create more art.</td>', 'Very nice, using art to create more art.', '2004-09-01 19:13:35.000000', NULL, 1),
(888627, 101196, 18799, '<td valign="top">Nice image, but IMO doesn''t meet the challenge</td>', 'Nice image, but IMO doesn''t meet the challenge', '2004-09-01 19:15:40.000000', NULL, 1),
(888630, 100369, 18799, '<td valign="top">Interesting concept - good job</td>', 'Interesting concept - good job', '2004-09-01 19:17:01.000000', NULL, 1),
(888638, 101699, 18799, '<td valign="top">I like the photo, and the sepia.  The bright light is a little much for me.</td>', 'I like the photo, and the sepia.  The bright light is a little much for me.', '2004-09-01 19:18:52.000000', NULL, 1),
(888643, 101001, 21034, '<td valign="top">I like the grass in this picture. Grass is nice.</td>', 'I like the grass in this picture. Grass is nice.', '2004-09-01 19:20:29.000000', NULL, 1),
