(890213, 101297, 24642, '<td valign="top">Good work.  Nice lighting and the mirror really adds a new dimention.</td>', 'Good work.  Nice lighting and the mirror really adds a new dimention.', '2004-09-02 20:00:08.000000', NULL, 1),
(890214, 100397, 24642, '<td valign="top">Very strong and straight to the point.  The title could be less obvious.</td>', 'Very strong and straight to the point.  The title could be less obvious.', '2004-09-02 20:02:34.000000', NULL, 1),
(890216, 101455, 24642, '<td valign="top">A bit below the waist for my taste.</td>', 'A bit below the waist for my taste.', '2004-09-02 20:04:34.000000', NULL, 1),
(890218, 101423, 24642, '<td valign="top">A good idea but the lighting could be improoved.</td>', 'A good idea but the lighting could be improoved.', '2004-09-02 20:05:39.000000', NULL, 1),
(890219, 100693, 22970, '<td valign="top">An ok job of framing but I think it would have been better if you would of focused closer to the iron fence and had a subject that stood out in the background.</td>', 'An ok job of framing but I think it would have been better if you would of focused closer to the iron fence and had a subject that stood out in the background.', '2004-09-02 20:06:36.000000', NULL, 1),
(890223, 101469, 24642, '<td valign="top">Good lighting but the composition could be improoved by cropping out or using differend focal lenght to get rid of distractions on the sides.</td>', 'Good lighting but the composition could be improoved by cropping out or using differend focal lenght to get rid of distractions on the sides.', '2004-09-02 20:08:03.000000', NULL, 1),
(890224, 100369, 24642, '<td valign="top">Too much framing, too little subject?</td>', 'Too much framing, too little subject?', '2004-09-02 20:09:14.000000', NULL, 1),
(890225, 101514, 22970, '<td valign="top">Picture had potential but way to small. Try to make use of the full 640 X . I think you would of scored higher. Good job of framing.</td>', 'Picture had potential but way to small. Try to make use of the full 640 X . I think you would of scored higher. Good job of framing.', '2004-09-02 20:09:16.000000', NULL, 1),
(890228, 101001, 22970, '<td valign="top">Great job of faming and creativity.</td>', 'Great job of faming and creativity.', '2004-09-02 20:10:37.000000', NULL, 1),
(890229, 101428, 24642, '<td valign="top">Good work.  Good abstraction.</td>', 'Good work.  Good abstraction.', '2004-09-02 20:11:03.000000', NULL, 1),
(890231, 101496, 24642, '<td valign="top">A very good frame and a matching title.</td>', 'A very good frame and a matching title.', '2004-09-02 20:12:13.000000', NULL, 1),
(890238, 101501, 24642, '<td valign="top">Good composition and lighting.  A strong shot, clean and peaceful.</td>', 'Good composition and lighting.  A strong shot, clean and peaceful.', '2004-09-02 20:15:32.000000', NULL, 1),
(890241, 101952, 24642, '<td valign="top">A  good idea and title but white is not an angry color.</td>', 'A  good idea and title but white is not an angry color.', '2004-09-02 20:22:12.000000', NULL, 1),
(890242, 101725, 24642, '<td valign="top">I like the lighting and viewpoint.  Nice colors.  The white wall on the right is a bit of a distraction.  I would have cropped it 20% from the bottom and from the right.</td>', 'I like the lighting and viewpoint.  Nice colors.  The white wall on the right is a bit of a distraction.  I would have cropped it 20% from the bottom and from the right.', '2004-09-02 20:25:42.000000', NULL, 1),
(890244, 100777, 22970, '<td valign="top">Very creative and in this shot the "TITLE" adds to the photograph.</td>', 'Very creative and in this shot the "TITLE" adds to the photograph.', '2004-09-02 20:27:12.000000', NULL, 1),
(890246, 101479, 10819, '<td valign="top">Is this at the birmingham botanical gardens?</td>', 'Is this at the birmingham botanical gardens?', '2004-09-02 20:28:09.000000', NULL, 1),
(890247, 101937, 24642, '<td valign="top">A shorter shutter speed would probably increase the sharpness and make a more striking effect in the lights.</td>', 'A shorter shutter speed would probably increase the sharpness and make a more striking effect in the lights.', '2004-09-02 20:28:10.000000', NULL, 1),
(890249, 100418, 24642, '<td valign="top">A strong composition with a matching title.</td>', 'A strong composition with a matching title.', '2004-09-02 20:29:28.000000', NULL, 1),
(890250, 101826, 21554, '<td valign="top">Lovely image.  the intensity of the eyes and the almost architectural lines of the foliage are a wonderful combination.</td>', 'Lovely image.  the intensity of the eyes and the almost architectural lines of the foliage are a wonderful combination.', '2004-09-02 20:29:47.000000', NULL, 1),
