INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(890256, 101454, 24642, '<td valign="top">A good compositon but the lighting is tough.</td>', 'A good compositon but the lighting is tough.', '2004-09-02 20:35:29.000000', NULL, 1),
(890260, 101807, 25065, '<td valign="top">I''m missing the frame part of the picture. The foreground trees don''t quite make a frame, IMO.</td>', 'I''m missing the frame part of the picture. The foreground trees don''t quite make a frame, IMO.', '2004-09-02 20:40:36.000000', NULL, 1),
(890266, 101317, 25065, '<td valign="top">I don''t see anything being framed. Perhaps there was an airplane window that got cropped out?</td>', 'I don''t see anything being framed. Perhaps there was an airplane window that got cropped out?', '2004-09-02 20:42:06.000000', NULL, 1),
(890267, 101928, 25065, '<td valign="top">I don''t think the ''mirror'' counts as a frame in the foreground, because it''s inthe background...</td>', 'I don''t think the ''mirror'' counts as a frame in the foreground, because it''s inthe background...', '2004-09-02 20:42:55.000000', NULL, 1),
(890268, 100838, 25065, '<td valign="top">I cant see much inthe picture, because of it being so dark...</td>', 'I cant see much inthe picture, because of it being so dark...', '2004-09-02 20:43:26.000000', NULL, 1),
(890270, 101660, 25065, '<td valign="top">I unfortunately fail tosee the frame in th.... Wait... I see it.... Hahahahahaahah! Great use of legs!!!! Here, have an 8 for good comedy!</td>', 'I unfortunately fail tosee the frame in th.... Wait... I see it.... Hahahahahaahah! Great use of legs!!!! Here, have an 8 for good comedy!', '2004-09-02 20:44:59.000000', NULL, 1),
(890272, 101680, 25065, '<td valign="top">Having problems seeing the frame in this pic...</td>', 'Having problems seeing the frame in this pic...', '2004-09-02 20:45:38.000000', NULL, 1),
(890273, 101275, 25065, '<td valign="top">I don''t know if the foreground mountans count as an actual frame, because it''s only 1 plane...</td>', 'I don''t know if the foreground mountans count as an actual frame, because it''s only 1 plane...', '2004-09-02 20:46:59.000000', NULL, 1),
(890274, 101795, 25065, '<td valign="top">Unfortunately, the blue "Frame" is in the background, and not the foreground...</td>', 'Unfortunately, the blue "Frame" is in the background, and not the foreground...', '2004-09-02 20:47:34.000000', NULL, 1),
(890275, 101199, 25065, '<td valign="top">Funny pic, but there''s nothing being framed....</td>', 'Funny pic, but there''s nothing being framed....', '2004-09-02 20:48:11.000000', NULL, 1),
(890283, 101517, 22010, '<td valign="top">I would like it a bit more if you had cropped out the sky in the upper left hand corner, but that might take away the whole arch effect. I still like a lot. One of my 7 favorites.</td>', 'I would like it a bit more if you had cropped out the sky in the upper left hand corner, but that might take away the whole arch effect. I still like a lot. One of my 7 favorites.', '2004-09-02 20:53:11.000000', NULL, 1),
(890286, 100514, 25065, '<td valign="top">I don''t think clouds count as a frame, but the treeline and spruce do.</td>', 'I don''t think clouds count as a frame, but the treeline and spruce do.', '2004-09-02 20:55:03.000000', NULL, 1),
(890289, 101463, 22010, '<td valign="top">I was there a couple of weeks ago! Nice picture. Although the sun setting casting that light on the right side of the frame is a bit distracting. Without the setting sun though, the view wouldn''t be as nice. One of my favorites so far.</td>', 'I was there a couple of weeks ago! Nice picture. Although the sun setting casting that light on the right side of the frame is a bit distracting. Without the setting sun though, the view wouldn''t be as nice. One of my favorites so far.', '2004-09-02 20:55:52.000000', NULL, 1),
(890291, 101533, 25065, '<td valign="top">Because the sky is a background element it doesn''t meet the criterium of the frame being a foreground subject...</td>', 'Because the sky is a background element it doesn''t meet the criterium of the frame being a foreground subject...', '2004-09-02 20:56:40.000000', NULL, 1),
(890292, 101738, 25065, '<td valign="top">Because the wall is a background element it doesn''t meet the criterium of the frame being a foreground subject...</td>', 'Because the wall is a background element it doesn''t meet the criterium of the frame being a foreground subject...', '2004-09-02 20:57:26.000000', NULL, 1),
