(892242, 101693, 10170, '<td valign="top">Simple and very well done indeed.</td>', 'Simple and very well done indeed.', '2004-09-04 01:37:18.000000', NULL, 1),
(892245, 100852, 14620, '<td valign="top">A very original and interesting take on the challenge.  Great colors and textures but the composition of this shot is what makes it special.  It''s very striking and very well done.</td>', 'A very original and interesting take on the challenge.  Great colors and textures but the composition of this shot is what makes it special.  It''s very striking and very well done.', '2004-09-04 01:38:24.000000', NULL, 1),
