(892247, 101588, 25143, '<td valign="top">very unusual way of focusing - the spiderweb and M shaped frame are big enough to carry the interest</td>', 'very unusual way of focusing - the spiderweb and M shaped frame are big enough to carry the interest', '2004-09-04 01:38:35.000000', NULL, 1),
(892250, 101823, 16046, '<td valign="top">Well done, nice composition</td>', 'Well done, nice composition', '2004-09-04 01:39:08.000000', NULL, 1),
