(892254, 101620, 25143, '<td valign="top">nice light and well-picked angle for the composition</td>', 'nice light and well-picked angle for the composition', '2004-09-04 01:40:15.000000', NULL, 1),
(892255, 101543, 14620, '<td valign="top">This is  a very dramatic shot and is a wonderful choice for this challenge.  The vibrant colors against the dark, colorless borders is very eye  catching.  I love the darkness of the shot and how the windows just glow from it.  Very beautiful!</td>', 'This is  a very dramatic shot and is a wonderful choice for this challenge.  The vibrant colors against the dark, colorless borders is very eye  catching.  I love the darkness of the shot and how the windows just glow from it.  Very beautiful!', '2004-09-04 01:40:16.000000', NULL, 1),
(892256, 101826, 16046, '<td valign="top">I don''t care for cat entries, but this one is great. Good contrast with the wiskers and eye color matches leaves. Well done.</td>', 'I don''t care for cat entries, but this one is great. Good contrast with the wiskers and eye color matches leaves. Well done.', '2004-09-04 01:41:35.000000', NULL, 1),
(892259, 101882, 16046, '<td valign="top">What makes this image is the reflection of the key hole, very spooky. You get a 10 from me.</td>', 'What makes this image is the reflection of the key hole, very spooky. You get a 10 from me.', '2004-09-04 01:43:05.000000', NULL, 1),
(892260, 100516, 25143, '<td valign="top">too much strife between the fire  - too distant and blurry - and the fern fronds  - a bit overexposed and out of focus - I would have preferred a more decided preference for one or the other</td>', 'too much strife between the fire  - too distant and blurry - and the fern fronds  - a bit overexposed and out of focus - I would have preferred a more decided preference for one or the other', '2004-09-04 01:43:34.000000', NULL, 1),
