(893817, 101317, 20433, '<td valign="top">Good photo but where is the frame ?</td>', 'Good photo but where is the frame ?', '2004-09-05 11:52:58.000000', NULL, 1),
(893821, 100862, 2000, '<td valign="top">Very creative framing elements - cars frame headlight which in turn frames another car.  Lighting and DOF are good too, and this is an interesting photo for it.</td>', 'Very creative framing elements - cars frame headlight which in turn frames another car.  Lighting and DOF are good too, and this is an interesting photo for it.', '2004-09-05 11:54:45.000000', NULL, 1),
(893822, 101508, 20433, '<td valign="top">Good one but the branch in front of the girl is a little distracting.</td>', 'Good one but the branch in front of the girl is a little distracting.', '2004-09-05 11:54:50.000000', NULL, 1),
(893823, 101870, 2000, '<td valign="top">Interesting use of a reflection to create a framing element.</td>', 'Interesting use of a reflection to create a framing element.', '2004-09-05 11:55:29.000000', NULL, 1),
(893825, 101935, 23312, '<td valign="top">Nead idea, I like the yellowish cast to everything.  I''d be tempted to try a tighter crop.</td>', 'Nead idea, I like the yellowish cast to everything.  I''d be tempted to try a tighter crop.', '2004-09-05 11:56:12.000000', NULL, 1),
