(893829, 101059, 20433, '<td valign="top">I would have liked to see stronger colors in this one. Good job.</td>', 'I would have liked to see stronger colors in this one. Good job.', '2004-09-05 11:58:35.000000', NULL, 1),
(893830, 101921, 2000, '<td valign="top">This might be a little more interesting if there was something other than clear blue sky visible through the bars, but I understand and appreciate the goal of the photo. 7</td>', 'This might be a little more interesting if there was something other than clear blue sky visible through the bars, but I understand and appreciate the goal of the photo. 7', '2004-09-05 11:59:36.000000', NULL, 1),
(893833, 101196, 20433, '<td valign="top">Excellent shot, but where is the framing ?</td>', 'Excellent shot, but where is the framing ?', '2004-09-05 12:01:04.000000', NULL, 1),
