(893916, 101800, 6870, '<td valign="top">I like the high contrast/high highlights here.</td>', 'I like the high contrast/high highlights here.', '2004-09-05 13:58:34.000000', NULL, 1),
(893917, 100369, 6870, '<td valign="top">Very intriguing, artistic vision expressed here. Nice work. I wish there were more light on the gentleman. Perhaps after the challenge you can simply dodge him a bit?</td>', 'Very intriguing, artistic vision expressed here. Nice work. I wish there were more light on the gentleman. Perhaps after the challenge you can simply dodge him a bit?', '2004-09-05 13:59:38.000000', NULL, 1),
(893918, 100514, 6870, '<td valign="top">I wanna come too! Lovely shot. I''m not sure the clouds act as a frame, but the tree does for sure, though I''m not sure the photo is helped by it. 8</td>', 'I wanna come too! Lovely shot. I''m not sure the clouds act as a frame, but the tree does for sure, though I''m not sure the photo is helped by it. 8', '2004-09-05 14:01:30.000000', NULL, 1),
