INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(893941, 101919, 19035, '<td valign="top">Great idea. Your model has a wonderful smile. - 8 -</td>', 'Great idea. Your model has a wonderful smile. - 8 -', '2004-09-05 14:26:59.000000', NULL, 1),
