(896561, 101916, 19608, '<td valign="top">Nice idea - well composed and exposed (pun NOT intended.)  Don''t care much for the gray border.  Overall an excellent submission.</td>', 'Nice idea - well composed and exposed (pun NOT intended.)  Don''t care much for the gray border.  Overall an excellent submission.', '2004-09-06 23:10:34.000000', NULL, 1),
(896562, 101849, 19608, '<td valign="top">Tree makes a very nice frame.  Love the pastel colors.</td>', 'Tree makes a very nice frame.  Love the pastel colors.', '2004-09-06 23:11:45.000000', NULL, 1),
(896567, 100514, 19608, '<td valign="top">An awesome shot!  Too bad there''s not more to the framing.</td>', 'An awesome shot!  Too bad there''s not more to the framing.', '2004-09-06 23:18:50.000000', NULL, 1),
