(897751, 101847, 11270, '<td valign="top">This is a great photograph, and the framing is just enough, I rate this a 10</td>', 'This is a great photograph, and the framing is just enough, I rate this a 10', '2004-09-07 18:19:05.000000', NULL, 1),
(897758, 100518, 24454, '<td valign="top">Awww. . . .this is so cute!  Great idea, and the contrast of colors makes it a nice, interesting picture.</td>', 'Awww. . . .this is so cute!  Great idea, and the contrast of colors makes it a nice, interesting picture.', '2004-09-07 18:25:56.000000', NULL, 1),
